// Shape of content/case-studies/<slug>.json (generated by scripts/import-framer.py).

export type Img = { src: string; alt: string; video?: string }; // video: local mp4 path (src is then its poster)
export type Card = { label: string; value: string };

export type DeviceShot = {
  src: string;
  alt: string;
  device: "iphone" | "duo-folded" | "duo-unfolded";
  caption?: string;
};

export type Block =
  | { type: "heading"; text: string }
  | { type: "paragraph"; text: string }
  | { type: "list"; items: string[] }
  | { type: "images"; images: Img[] }
  | { type: "cards"; cards: Card[] }
  | { type: "video"; vimeoId: string }
  | { type: "embed"; src: string }
  // Visual blocks rebuilt from Framer captures (scripts/visual-blocks.py)
  | { type: "figure"; image: Img; caption?: string; wide?: boolean }
  | { type: "loop"; src: string; poster: string; caption?: string; wide?: boolean }
  | { type: "metrics"; items: Metric[] }
  | { type: "widgets"; items: Widget[] }
  // Process section as a bento grid: one tile per heading (scripts/visual-blocks.py).
  | { type: "bento"; items: BentoTile[] }
  | { type: "devices"; items: DeviceShot[]; caption?: string };

export type BentoTile = {
  title: string; // the main point, shown on the closed note
  condensed: string; // shown when the note flips open
  source: Block[]; // the original paragraphs/lists, kept for screen readers and "Full notes"
};

export type Metric = { value: string; label: string };

export type Widget = {
  title: string;
  subtitle: string;
  preview: Img;
  code: { swiftui: string; flutter: string; tailwind: string };
};

export type Section = { label: string; blocks: Block[] };

export type CaseStudy = {
  slug: string;
  title: string;
  description: string;
  tags: string[];
  hmw: string; // completes the sentence "How might we …"
  facts: Card[]; // values may contain "\n" line breaks
  prototype: { embed: string; link: string | null; aspect?: string } | null; // aspect: CSS ratio the prototype letterboxes to
  heroImages: Img[];
  heroFit?: "contain";
  sections: Section[]; // a section's label may be "" (untitled intro section)
  unportedComponents: string[];
  imageCount: number;
};
